/**
 * SceneManager - 场景管理器
 * 统一管理WebGL渲染器和布局切换
 */

import { WebGLNodeRenderer } from './WebGLNodeRenderer';
import LayoutManager from './LayoutManager';

const BUTTON_COLOR_NEUTRAL = [0.56, 0.62, 0.68, 0.92];
const BUTTON_COLOR_NEUTRAL_SOFT = [0.42, 0.48, 0.55, 0.88];
const BUTTON_COLOR_DISABLED = [0.38, 0.43, 0.5, 0.78];
const BUTTON_COLOR_ALERT = [0.78, 0.42, 0.34, 0.94];

class SceneManager {
  constructor(canvas) {
    this.canvas = canvas;
    this.renderer = new WebGLNodeRenderer(canvas);
    this.layout = new LayoutManager(canvas.width, canvas.height);

    this.currentScene = null;  // 'home' | 'nodeDetail' | 'titleDetail'
    this.currentLayout = { nodes: [], lines: [] };
    this.currentLayoutSource = null;
    this.pendingStarMapMeasuredLabelPass = 0;
    this.activeStarMapMeasuredLabelKey = '';
    this.completedStarMapMeasuredLabelKeys = new Set();
    this.layoutTransitionVersion = 0;
    this.pendingTransitionTimeouts = new Set();

    // 回调函数
    this.onNodeClick = null;
    this.onNodeDoubleClick = null;
    this.onSceneChange = null;
    this.onBlankClick = null;
    this.onButtonClick = null; // 按钮点击回调
    this.onLineClick = null; // 连线点击回调
    this.onStarMapViewportChange = null;

    // 预览模式状态
    this.isInPreviewMode = false;
    this.previewConfig = null;
    this.centerNodeButtonContext = {};
    this.preferredStarMapZoom = 1;

    // 绑定点击事件
    this.renderer.onClick = (node) => {
      if (this.onNodeClick) {
        this.onNodeClick(node);
      }
    };

    this.renderer.onDoubleClick = (node) => {
      if (this.onNodeDoubleClick) {
        this.onNodeDoubleClick(node);
      }
    };
    this.renderer.onBlankClick = () => {
      if (this.onBlankClick) {
        this.onBlankClick();
      }
    };

    // 绑定按钮点击事件
    this.renderer.onButtonClick = (nodeId, button) => {
      if (this.onButtonClick) {
        this.onButtonClick(nodeId, button);
      }
    };
    this.renderer.onLineClick = (lineHit) => {
      if (this.onLineClick) {
        this.onLineClick(lineHit);
      }
    };
    this.renderer.onPinchZoom = (zoom) => {
      if (this.currentLayout?.meta?.type !== 'starMap') return;
      this.preferredStarMapZoom = this.resolveStarMapZoom(this.currentLayout, zoom);
      this.emitStarMapViewportChange(this.currentLayout);
    };
  }

  resetCameraToLayoutCenter() {
    this.renderer.setCameraZoom(1, { render: false });
    this.renderer.setCameraOffset(0, 0);
  }

  resolveMainViewViewportInsets() {
    if (typeof window === 'undefined' || typeof document === 'undefined' || !this.canvas) {
      return { top: 0, right: 0, bottom: 0, left: 0 };
    }

    const canvasRect = this.canvas.getBoundingClientRect();
    if (!canvasRect || canvasRect.width <= 0 || canvasRect.height <= 0) {
      return { top: 0, right: 0, bottom: 0, left: 0 };
    }

    const hasOverlap = (rect) => (
      rect
      && rect.width > 0
      && rect.height > 0
      && rect.right > canvasRect.left
      && rect.left < canvasRect.right
      && rect.bottom > canvasRect.top
      && rect.top < canvasRect.bottom
    );
    const isVisible = (element) => {
      const style = window.getComputedStyle(element);
      return style.display !== 'none' && style.visibility !== 'hidden' && Number(style.opacity) !== 0;
    };

    let top = 0;
    let floatingTopPanelInset = 0;
    let left = 0;
    document.querySelectorAll('.header:not(.header-mobile-suppressed)').forEach((element) => {
      if (!isVisible(element)) return;
      const rect = element.getBoundingClientRect();
      if (!hasOverlap(rect)) return;
      top = Math.max(top, rect.bottom - canvasRect.top);
    });
    document.querySelectorAll('.node-detail-top-overlay').forEach((element) => {
      if (!isVisible(element)) return;
      const rect = element.getBoundingClientRect();
      if (!hasOverlap(rect)) return;
      const overlapHeight = Math.max(0, rect.bottom - Math.max(rect.top, canvasRect.top));
      floatingTopPanelInset = Math.max(floatingTopPanelInset, overlapHeight * 0.32);
    });

    document.querySelectorAll('.navigation-sidebar, .navigation-sidebar__edge-tab').forEach((element) => {
      if (!isVisible(element)) return;
      const rect = element.getBoundingClientRect();
      if (!hasOverlap(rect)) return;
      left = Math.max(left, rect.right - canvasRect.left);
    });

    return {
      top: Math.max(0, Math.min(canvasRect.height * 0.32, top + floatingTopPanelInset)),
      right: 0,
      bottom: 0,
      left: Math.max(0, Math.min(canvasRect.width * 0.45, left))
    };
  }

  refreshMainViewViewportInsets() {
    const insets = this.resolveMainViewViewportInsets();
    this.layout.setViewportInsets(insets);
    return insets;
  }

  getStarMapZoomBounds(layout = this.currentLayout) {
    const fallback = {
      min: 0.5,
      max: 1.12,
      defaultValue: 1
    };
    if (layout?.meta?.type !== 'starMap') {
      return fallback;
    }

    const bounds = layout?.bounds;
    const canvasWidth = Math.max(1, Number(this.canvas?.width) || Number(this.layout?.width) || 1);
    const canvasHeight = Math.max(1, Number(this.canvas?.height) || Number(this.layout?.height) || 1);
    const boundsWidth = Math.max(1, Number(bounds?.width) || 1);
    const boundsHeight = Math.max(1, Number(bounds?.height) || 1);
    const isDesktopViewport = canvasWidth > 768;
    const paddedWidth = Math.max(
      1,
      canvasWidth - (isDesktopViewport ? 420 : 240)
    );
    const paddedHeight = Math.max(
      1,
      canvasHeight - (isDesktopViewport ? 260 : 180)
    );
    const fitZoom = Math.min(paddedWidth / boundsWidth, paddedHeight / boundsHeight);

    if (!isDesktopViewport) {
      return {
        min: Math.max(0.22, Math.min(1, fitZoom)),
        max: 1.12,
        defaultValue: 1
      };
    }

    const defaultValue = Math.max(0.28, Math.min(1, fitZoom));
    const min = Math.max(0.22, Math.min(defaultValue, defaultValue * 0.82));
    const max = Math.max(defaultValue, Math.min(1.28, Math.max(defaultValue * 1.42, defaultValue + 0.24)));

    return {
      min,
      max,
      defaultValue
    };
  }

  getStarMapZoomState(layout = this.currentLayout) {
    const bounds = this.getStarMapZoomBounds(layout);
    const value = Math.max(bounds.min, Math.min(bounds.max, Number(this.renderer?.camera?.zoom) || bounds.defaultValue));
    return {
      ...bounds,
      value
    };
  }

  syncStarMapInteractionConfig(layout = this.currentLayout) {
    if (layout?.meta?.type !== 'starMap') {
      this.renderer.setPinchZoomOptions({ enabled: false });
      return;
    }

    const bounds = this.getStarMapZoomBounds(layout);
    this.renderer.setPinchZoomOptions({
      enabled: true,
      min: bounds.min,
      max: bounds.max
    });
  }

  emitStarMapViewportChange(layout = this.currentLayout) {
    if (typeof this.onStarMapViewportChange !== 'function') return;
    this.onStarMapViewportChange(this.getStarMapZoomState(layout));
  }

  resolveStarMapZoom(layout = this.currentLayout, requestedZoom = this.preferredStarMapZoom) {
    const bounds = this.getStarMapZoomBounds(layout);
    const normalizedZoom = Number.isFinite(Number(requestedZoom)) ? Number(requestedZoom) : bounds.defaultValue;
    return Math.max(bounds.min, Math.min(bounds.max, normalizedZoom));
  }

  applyStarMapFraming(layout = this.currentLayout, requestedZoom = this.preferredStarMapZoom) {
    const bounds = layout?.bounds;
    if (!bounds) {
      this.resetCameraToLayoutCenter();
      return;
    }

    const zoom = this.resolveStarMapZoom(layout, requestedZoom);
    this.preferredStarMapZoom = zoom;

    const centerNode = Array.isArray(layout?.nodes)
      ? layout.nodes.find((node) => node?.type === 'center' && node?.visible !== false)
      : null;
    const contentCenterX = Number.isFinite(Number(centerNode?.x))
      ? Number(centerNode.x)
      : bounds.left + bounds.width * 0.5;
    const contentCenterY = Number.isFinite(Number(centerNode?.y))
      ? Number(centerNode.y)
      : bounds.top + bounds.height * 0.5;
    const viewportCenter = this.layout.getViewportFocusCenter();
    const viewportCenterX = viewportCenter.centerX;
    const viewportCenterY = viewportCenter.centerY;
    this.renderer.setCameraZoom(zoom, { render: false });
    this.renderer.setCameraOffset(
      viewportCenterX - contentCenterX * zoom,
      viewportCenterY - contentCenterY * zoom,
      { render: false }
    );
    this.renderer.render();
    this.emitStarMapViewportChange(layout);
  }

  frameStarMapOnCenter(layout = this.currentLayout, requestedZoom = this.preferredStarMapZoom) {
    if (layout?.meta?.type !== 'starMap') return;
    this.refreshMainViewViewportInsets();
    this.applyStarMapFraming(layout, requestedZoom);
  }

  scheduleStarMapCenterRefit(transitionVersion = null) {
    this.scheduleTransitionTimeout(() => {
      if (!this.isLayoutTransitionCurrent(transitionVersion)) return;
      if (this.currentLayout?.meta?.type !== 'starMap') return;
      this.frameStarMapOnCenter(this.currentLayout, this.preferredStarMapZoom);
    }, 0);
  }

  setStarMapZoom(zoom = this.preferredStarMapZoom, layout = this.currentLayout) {
    if (layout?.meta?.type !== 'starMap') return null;
    const resolvedZoom = this.resolveStarMapZoom(layout, zoom);
    this.preferredStarMapZoom = resolvedZoom;
    this.frameStarMapOnCenter(layout, resolvedZoom);
    return this.getStarMapZoomState(layout);
  }

  cancelPendingStarMapMeasuredLabelPass() {
    if (this.pendingStarMapMeasuredLabelPass) {
      cancelAnimationFrame(this.pendingStarMapMeasuredLabelPass);
      this.pendingStarMapMeasuredLabelPass = 0;
    }
    this.activeStarMapMeasuredLabelKey = '';
  }

  clearPendingTransitionTimeouts() {
    if (this.pendingTransitionTimeouts.size < 1) return;
    this.pendingTransitionTimeouts.forEach((timeoutId) => clearTimeout(timeoutId));
    this.pendingTransitionTimeouts.clear();
  }

  scheduleTransitionTimeout(callback, delay = 0) {
    const timeoutId = setTimeout(() => {
      this.pendingTransitionTimeouts.delete(timeoutId);
      callback();
    }, delay);
    this.pendingTransitionTimeouts.add(timeoutId);
    return timeoutId;
  }

  previewNodeActivation(node) {
    this.renderer.previewNodeActivation(node);
  }

  beginLayoutTransition({ cancelAnimations = true, cancelMeasuredLabelPass = false, restoreStableLayout = false } = {}) {
    const hadPendingVisualTransition = this.pendingTransitionTimeouts.size > 0
      || this.renderer.animations.length > 0
      || this.renderer.animating;
    this.layoutTransitionVersion += 1;
    this.clearPendingTransitionTimeouts();
    if (cancelMeasuredLabelPass) {
      this.cancelPendingStarMapMeasuredLabelPass();
    }
    if (cancelAnimations) {
      this.renderer.cancelAllAnimations();
    }
    if (restoreStableLayout && hadPendingVisualTransition && this.currentLayout) {
      this.setLayout(this.currentLayout);
      if (this.currentLayout?.meta?.type === 'starMap') {
        this.frameStarMapOnCenter(this.currentLayout);
      } else {
        this.resetCameraToLayoutCenter();
      }
    }
    return {
      version: this.layoutTransitionVersion,
      hadPendingVisualTransition
    };
  }

  isLayoutTransitionCurrent(transitionVersion) {
    if (!Number.isFinite(Number(transitionVersion))) return true;
    return this.layoutTransitionVersion === Number(transitionVersion);
  }

  scheduleStarMapMeasuredLabelPass(layout = this.currentLayout) {
    const layoutKey = layout?.meta?.layoutKey;
    if (layout?.meta?.type !== 'starMap' || !layoutKey) return;
    if (this.completedStarMapMeasuredLabelKeys.has(layoutKey)) return;

    this.cancelPendingStarMapMeasuredLabelPass();
    this.activeStarMapMeasuredLabelKey = layoutKey;

    let remainingFrames = 2;
    const runMeasuredPass = () => {
      const currentLayoutKey = this.currentLayout?.meta?.layoutKey;
      if (this.currentLayout?.meta?.type !== 'starMap' || currentLayoutKey !== layoutKey) {
        this.pendingStarMapMeasuredLabelPass = 0;
        this.activeStarMapMeasuredLabelKey = '';
        return;
      }

      if (remainingFrames > 0) {
        remainingFrames -= 1;
        this.pendingStarMapMeasuredLabelPass = requestAnimationFrame(runMeasuredPass);
        return;
      }

      this.pendingStarMapMeasuredLabelPass = 0;
      this.activeStarMapMeasuredLabelKey = '';
      const measuredLabelBoxes = this.renderer.getMeasuredStarMapLabelBoxes();
      const refined = this.layout.refineStarMapLayoutWithMeasuredLabels(this.currentLayout, measuredLabelBoxes);
      this.completedStarMapMeasuredLabelKeys.add(layoutKey);

      if (refined?.applied && refined.layout?.meta?.layoutKey === layoutKey) {
        this.setLayout(refined.layout);
        this.frameStarMapOnCenter(refined.layout);
      } else if (refined?.layout?.debug) {
        this.renderer.setLayoutDebugData(refined.layout.debug);
        this.renderer.render();
      }
    };

    this.pendingStarMapMeasuredLabelPass = requestAnimationFrame(runMeasuredPass);
  }

  /**
   * 显示首页场景
   */
  async showHome(rootNodes, featuredNodes, searchResults = []) {
    const {
      version: transitionVersion
    } = this.beginLayoutTransition({
      cancelAnimations: true,
      cancelMeasuredLabelPass: true,
      restoreStableLayout: true
    });

    this.renderer.setSceneType('home');
    this.renderer.setCameraPanEnabled(false);
    this.resetCameraToLayoutCenter();

    // 清除节点按钮（首页不需要）
    this.renderer.clearNodeButtons();

    const newLayout = this.layout.calculateHomeLayout(rootNodes, featuredNodes, searchResults);
    this.currentLayoutSource = {
      mode: 'main',
      scene: 'home',
      rootNodes,
      featuredNodes,
      searchResults
    };

    if (this.currentScene === null) {
      // 首次加载：直接设置
      if (!this.isLayoutTransitionCurrent(transitionVersion)) return;
      this.setLayout(newLayout);
      this.currentScene = 'home';
    } else if (this.currentScene === 'home') {
      // 已在首页：平滑过渡 (搜索切换)
      await this.transitionTo(newLayout, 500, transitionVersion);
    } else {
      // 从其他场景返回首页：淡出当前，淡入新场景
      await this.fadeTransition(newLayout, 400, transitionVersion);
    }

    if (!this.isLayoutTransitionCurrent(transitionVersion)) return;
    this.currentScene = 'home';

    if (this.onSceneChange) {
      this.onSceneChange('home');
    }
  }

  /**
   * 显示节点详情场景
   */
  async showNodeDetail(centerNode, parentNodes, childNodes, clickedNode = null, buttonContext = {}) {
    const {
      version: transitionVersion
    } = this.beginLayoutTransition({
      cancelAnimations: true,
      cancelMeasuredLabelPass: true,
      restoreStableLayout: true
    });

    this.renderer.setSceneType('nodeDetail');
    this.renderer.setCameraPanEnabled(false);
    this.resetCameraToLayoutCenter();
    this.refreshMainViewViewportInsets();
    this.centerNodeButtonContext = buttonContext || {};

    // 清除之前的按钮
    this.renderer.clearNodeButtons();

    const newLayout = this.layout.calculateNodeDetailLayout(centerNode, parentNodes, childNodes);
    this.currentLayoutSource = {
      mode: 'main',
      scene: 'nodeDetail',
      centerNode,
      parentNodes,
      childNodes
    };

    // 如果当前场景没有节点或者是第一次加载，直接设置布局
    if (this.currentLayout.nodes.length === 0 || this.currentScene === null) {
      if (!this.isLayoutTransitionCurrent(transitionVersion)) return;
      this.setLayout(newLayout);
      this.setupCenterNodeButtons(centerNode, buttonContext);
      this.currentScene = 'nodeDetail';
      this.resetCameraToLayoutCenter();
      if (this.onSceneChange) {
        this.onSceneChange('nodeDetail', centerNode);
      }
      return;
    }

    if (this.currentScene === 'home' && clickedNode) {
      // 从首页点击节点：特殊过渡动画
      await this.clickTransition(clickedNode, newLayout, 620, transitionVersion);
    } else if (this.currentScene === 'nodeDetail') {
      // 节点详情之间切换
      await this.nodeToNodeTransition(clickedNode, newLayout, 360, transitionVersion);
    } else if (this.currentScene === 'titleDetail') {
      await this.titleSenseOrbitTransition(newLayout, 'titleToSense', 330, transitionVersion, clickedNode);
    } else {
      // 其他情况：直接设置布局
      this.setLayout(newLayout);
    }

    if (!this.isLayoutTransitionCurrent(transitionVersion)) return;

    // 设置中心节点的操作按钮
    this.setupCenterNodeButtons(centerNode, buttonContext);

    this.currentScene = 'nodeDetail';
    this.resetCameraToLayoutCenter();

    if (this.onSceneChange) {
      this.onSceneChange('nodeDetail', centerNode);
    }
  }

  /**
   * 显示标题主视角场景
   */
  async showTitleDetail(centerNode, graphNodes = [], graphEdges = [], levelByNodeId = {}, clickedNode = null, buttonContext = {}) {
    const {
      version: transitionVersion
    } = this.beginLayoutTransition({
      cancelAnimations: true,
      cancelMeasuredLabelPass: true,
      restoreStableLayout: true
    });

    this.renderer.setSceneType('titleDetail');
    this.renderer.setCameraPanEnabled(false);
    this.resetCameraToLayoutCenter();
    this.refreshMainViewViewportInsets();
    this.centerNodeButtonContext = buttonContext || {};
    this.renderer.clearNodeButtons();

    const newLayout = this.layout.calculateTitleDetailLayout(centerNode, graphNodes, graphEdges, levelByNodeId);
    this.currentLayoutSource = {
      mode: 'main',
      scene: 'titleDetail',
      centerNode,
      graphNodes,
      graphEdges,
      levelByNodeId
    };

    if (this.currentLayout.nodes.length === 0 || this.currentScene === null) {
      if (!this.isLayoutTransitionCurrent(transitionVersion)) return;
      this.setLayout(newLayout);
      this.setupCenterNodeButtons(centerNode, buttonContext);
      this.currentScene = 'titleDetail';
      this.resetCameraToLayoutCenter();
      if (this.onSceneChange) {
        this.onSceneChange('titleDetail', centerNode);
      }
      return;
    }

    if (this.currentScene === 'home' && clickedNode) {
      await this.clickTransition(clickedNode, newLayout, 620, transitionVersion);
    } else if (this.currentScene === 'titleDetail') {
      await this.nodeToNodeTransition(clickedNode, newLayout, 360, transitionVersion);
    } else if (this.currentScene === 'nodeDetail') {
      await this.titleSenseOrbitTransition(newLayout, 'senseToTitle', 330, transitionVersion, clickedNode);
    } else {
      await this.fadeTransition(newLayout, 400, transitionVersion);
    }

    if (!this.isLayoutTransitionCurrent(transitionVersion)) return;

    this.setupCenterNodeButtons(centerNode, buttonContext);
    this.currentScene = 'titleDetail';
    this.resetCameraToLayoutCenter();

    if (this.onSceneChange) {
      this.onSceneChange('titleDetail', centerNode);
    }
  }

  async showStarMap(scene, graph = {}, clickedNode = null) {
    if (scene !== 'titleDetail' && scene !== 'nodeDetail') return;
    const {
      version: transitionVersion,
      hadPendingVisualTransition
    } = this.beginLayoutTransition({
      cancelAnimations: true,
      cancelMeasuredLabelPass: true,
      restoreStableLayout: true
    });

    this.renderer.setSceneType(scene);
    this.renderer.setCameraPanEnabled(true);
    this.resetCameraToLayoutCenter();
    this.refreshMainViewViewportInsets();
    this.centerNodeButtonContext = {};
    this.renderer.clearNodeButtons();

    const layer = scene === 'titleDetail' ? 'title' : 'sense';
    const newLayout = this.layout.calculateStarMapLayout(graph, { layer });
    this.preferredStarMapZoom = this.getStarMapZoomBounds(newLayout).defaultValue;
    this.currentLayoutSource = {
      mode: 'starMap',
      scene,
      graph
    };

    if (this.currentLayout.nodes.length === 0 || this.currentScene === null) {
      if (!this.isLayoutTransitionCurrent(transitionVersion)) return;
      this.setLayout(newLayout);
      this.currentScene = scene;
      this.frameStarMapOnCenter(newLayout);
      this.scheduleStarMapCenterRefit(transitionVersion);
      this.scheduleStarMapMeasuredLabelPass(newLayout);
      if (this.onSceneChange) {
        this.onSceneChange(scene, graph?.centerNode || null);
      }
      return;
    }

    if (hadPendingVisualTransition) {
      if (!this.isLayoutTransitionCurrent(transitionVersion)) return;
      this.setLayout(newLayout);
      this.currentScene = scene;
      this.frameStarMapOnCenter(newLayout);
      this.scheduleStarMapCenterRefit(transitionVersion);
      this.scheduleStarMapMeasuredLabelPass(newLayout);

      if (this.onSceneChange) {
        this.onSceneChange(scene, graph?.centerNode || null);
      }
      return;
    }

    if (this.currentScene !== scene) {
      await this.fadeTransition(newLayout, 320, transitionVersion);
    } else if (clickedNode) {
      await this.nodeToNodeTransition(clickedNode, newLayout, 360, transitionVersion);
    } else {
      await this.transitionTo(newLayout, 360, transitionVersion);
    }

    if (!this.isLayoutTransitionCurrent(transitionVersion)) return;
    this.currentScene = scene;
    this.frameStarMapOnCenter(newLayout);
    this.scheduleStarMapCenterRefit(transitionVersion);
    this.scheduleStarMapMeasuredLabelPass(newLayout);

    if (this.onSceneChange) {
      this.onSceneChange(scene, graph?.centerNode || null);
    }
  }

  /**
   * 设置中心节点的操作按钮
   */
  setupCenterNodeButtons(centerNode, buttonContext = this.centerNodeButtonContext || {}) {
    if (!centerNode) return;

    const centerNodeId = `center-${centerNode._id}`;
    if (buttonContext?.disableDefault) {
      this.renderer.setNodeButtons(centerNodeId, []);
      return;
    }
    const isFavorite = !!buttonContext.isFavorite;

    if (buttonContext?.senseFocus || buttonContext?.senseDetailOnly) {
      const senseButtons = [
        {
          id: 'toggle-favorite',
          icon: isFavorite ? '★' : '☆',
          angle: -Math.PI / 5,
          action: 'toggleFavoriteNode',
          tooltip: isFavorite ? '取消收藏' : '收藏该释义',
          color: BUTTON_COLOR_NEUTRAL_SOFT,
          size: 30,
          distance: 25,
          iconSize: 14
        },
        {
          id: 'sense-entry',
          icon: 'i',
          angle: Math.PI / 5,
          action: 'showSenseEntry',
          tooltip: '查看释义详情',
          color: BUTTON_COLOR_NEUTRAL,
          size: 30,
          distance: 25,
          iconSize: 14
        }
      ];

      this.renderer.setNodeButtons(centerNodeId, senseButtons);
      this.setupTitleAnchorButtons(centerNode, buttonContext);
      return;
    }

    const buttons = [
      {
        id: 'enter-domain',
        icon: '◎',  // 使用圆圈符号表示进入
        angle: -Math.PI / 7, // 右上偏侧，避开顶部连线区域
        action: 'enterKnowledgeDomain',
        tooltip: '进入知识域',
        color: BUTTON_COLOR_NEUTRAL
      },
      {
        id: 'toggle-favorite',
        icon: isFavorite ? '★' : '☆',
        angle: Math.PI / 7, // 右下偏侧，避开底部连线区域
        action: 'toggleFavoriteNode',
        tooltip: isFavorite ? '取消收藏' : '收藏该知识域',
        color: BUTTON_COLOR_NEUTRAL_SOFT
      }
    ];

    if (buttonContext.showDistributionButton) {
      buttons.push({
        id: 'join-distribution',
        icon: '✦',
        angle: -Math.PI * 0.62,
        action: 'joinDistribution',
        tooltip: '知识点分发',
        color: BUTTON_COLOR_NEUTRAL,
        disabled: !!buttonContext.distributionDisabled
      });
    }

    if (buttonContext.showMoveButton) {
      buttons.push({
        id: 'move-to-node',
        icon: '⇦',
        angle: Math.PI, // 左侧
        action: 'moveToNode',
        tooltip: buttonContext.moveDisabled
          ? (buttonContext.moveDisabledReason || '当前不可移动')
          : '移动到该节点',
        color: buttonContext.moveDisabled
          ? BUTTON_COLOR_DISABLED
          : BUTTON_COLOR_NEUTRAL,
        disabled: !!buttonContext.moveDisabled
      });
    }

    if (buttonContext.showIntelStealButton) {
      buttons.push({
        id: 'intel-heist',
        icon: buttonContext.intelStealHasSnapshot ? '◉' : '◌',
        angle: Math.PI * 0.62,
        action: 'intelSteal',
        tooltip: buttonContext.intelStealTooltip || '情报窃取',
        color: buttonContext.intelStealHasSnapshot
          ? BUTTON_COLOR_ALERT
          : BUTTON_COLOR_NEUTRAL_SOFT,
        disabled: !!buttonContext.intelStealDisabled
      });
    }

    if (buttonContext.showSiegeButton) {
      buttons.push({
        id: 'siege-domain',
        icon: buttonContext.siegeActive ? '⚔' : '✦',
        angle: -Math.PI * 0.86,
        action: 'siegeDomain',
        tooltip: buttonContext.siegeTooltip || '攻占知识域',
        color: buttonContext.siegeActive
          ? BUTTON_COLOR_ALERT
          : BUTTON_COLOR_NEUTRAL_SOFT,
        disabled: !!buttonContext.siegeDisabled
      });
    }

    if (this.renderer?.sceneType === 'titleDetail') {
      const titleButtons = this.arrangeTitleNodeButtons(buttons, centerNodeId);
      this.renderer.setNodeButtons(centerNodeId, titleButtons);
      return;
    }

    this.renderer.setNodeButtons(centerNodeId, buttons);
  }

  arrangeTitleNodeButtons(buttons = [], centerNodeId = '') {
    const node = this.renderer.nodes.get(centerNodeId);
    const radius = Math.max(48, Number(node?.radius) || 72);
    const innerX = -(radius + 34);
    const outerX = -(radius + 70);
    const rowGap = 34;
    return buttons.map((button, index) => {
      const column = index % 2;
      const row = Math.floor(index / 2);
      const offsetY = (row - 1) * rowGap + (column === 0 ? -8 : 8);
      return {
        ...button,
        angle: Math.PI,
        offsetX: column === 0 ? innerX : outerX,
        offsetY,
        size: Number(button?.size) || 28,
        hitRadius: Number(button?.hitRadius) || 18,
        iconSize: Number(button?.iconSize) || 13,
        distance: 0
      };
    });
  }

  setupTitleAnchorButtons(centerNode, buttonContext = this.centerNodeButtonContext || {}) {
    if (!centerNode?._id) return;
    const titleAnchorId = `title-anchor-${centerNode._id}`;
    if (this.renderer?.sceneType === 'nodeDetail') {
      this.renderer.setNodeButtons(titleAnchorId, []);
      return;
    }
    const anchorButtons = [
      {
        id: 'open-title-detail',
        icon: '⬡',
        angle: Math.PI * 0.16,
        action: 'openTitleDetail',
        tooltip: '切到标题主视角',
        color: BUTTON_COLOR_NEUTRAL,
        size: 24,
        distance: 15,
        hitRadius: 17,
        iconSize: 12
      }
    ];

    if (buttonContext.showSiegeButton) {
      anchorButtons.push({
        id: 'title-siege-domain',
        icon: buttonContext.siegeActive ? '⚔' : '✦',
        angle: Math.PI * 0.47,
        action: 'siegeDomain',
        tooltip: buttonContext.siegeTooltip || '攻占知识域',
        color: buttonContext.siegeActive ? BUTTON_COLOR_ALERT : BUTTON_COLOR_NEUTRAL_SOFT,
        disabled: !!buttonContext.siegeDisabled,
        size: 24,
        distance: 15,
        hitRadius: 17,
        iconSize: 12
      });
    }

    this.renderer.setNodeButtons(titleAnchorId, anchorButtons);
  }

  setupSenseDetailButton(centerNode) {
    if (!centerNode?._id) return;
    this.setupCenterNodeButtons(centerNode, {
      ...this.centerNodeButtonContext,
      senseFocus: true,
      showSenseEntryButton: true
    });
  }

  clearNodeButtons() {
    this.renderer.clearNodeButtons();
  }

  /**
   * 直接设置布局 (无动画)
   */
  setLayout(layout) {
    if (layout?.meta?.type !== 'starMap') {
      this.cancelPendingStarMapMeasuredLabelPass();
    }
    this.renderer.clearNodes();
    this.renderer.setLayoutDebugData(layout?.debug || null);

    for (const nodeConfig of layout.nodes) {
      this.renderer.setNode(nodeConfig.id, nodeConfig);
    }

    this.renderer.setLines(layout.lines);
    this.currentLayout = layout;
    this.syncStarMapInteractionConfig(layout);
    this.renderer.render();
  }

  setUserState(locationName, travelStatus) {
    this.renderer.setUserState({ locationName, travelStatus });
  }

  async titleSenseOrbitTransition(newLayout, direction = 'titleToSense', duration = 330, transitionVersion = null, clickedNode = null) {
    if (!this.isLayoutTransitionCurrent(transitionVersion)) return;
    const newCenterConfig = newLayout.nodes.find((node) => node.type === 'center');
    if (!newCenterConfig) {
      await this.fadeTransition(newLayout, duration, transitionVersion);
      return;
    }

    const newNodeIds = new Set(newLayout.nodes.map((node) => node.id));
    const currentCenterNode = Array.from(this.renderer.nodes.values()).find((node) => node.type === 'center');
    const currentTitleAnchor = Array.from(this.renderer.nodes.values()).find((node) => node.type === 'title-anchor');
    const newTitleAnchorConfig = newLayout.nodes.find((node) => node.type === 'title-anchor');

    this.renderer.setLines([]);

    if (direction === 'titleToSense' && currentCenterNode && newTitleAnchorConfig) {
      const clickedSenseNode = clickedNode?.id ? this.renderer.nodes.get(clickedNode.id) : null;
      const senseSourceNode = clickedSenseNode?.data?.detailRole === 'title-sense'
        ? clickedSenseNode
        : Array.from(this.renderer.nodes.values()).find((node) => node?.data?.detailRole === 'title-sense');
      this.renderer.setNode(newTitleAnchorConfig.id, {
        ...currentCenterNode,
        ...newTitleAnchorConfig,
        id: newTitleAnchorConfig.id,
        x: currentCenterNode.x,
        y: currentCenterNode.y,
        radius: currentCenterNode.radius,
        scale: 1,
        opacity: 0.92,
        rotation: -0.16,
        type: 'title-anchor'
      });

      if (senseSourceNode && senseSourceNode.id !== newCenterConfig.id) {
        this.renderer.setNode(newCenterConfig.id, {
          ...newCenterConfig,
          id: newCenterConfig.id,
          type: 'center',
          x: senseSourceNode.x,
          y: senseSourceNode.y,
          radius: senseSourceNode.radius,
          scale: Number(senseSourceNode.scale) || 1,
          opacity: Math.max(0.88, Math.min(1, Number(senseSourceNode.opacity) || 1)),
          rotation: Number(senseSourceNode.rotation) || 0
        });
      }

      const exitAnimations = [];
      for (const [nodeId, node] of this.renderer.nodes) {
        if (nodeId === currentCenterNode.id || nodeId === newTitleAnchorConfig.id || nodeId === newCenterConfig.id) continue;
        const directionX = node.x - currentCenterNode.x;
        const directionY = node.y - currentCenterNode.y;
        const distance = Math.hypot(directionX, directionY) || 1;
        exitAnimations.push(this.renderer.animateNode(nodeId, {
          x: node.x + (directionX / distance) * 130,
          y: node.y + (directionY / distance) * 130,
          scale: node.scale * 0.42,
          opacity: 0,
          rotation: node.rotation + (directionX >= 0 ? 0.16 : -0.16)
        }, duration * 0.26, 'easeInCubic'));
      }

      const anchorAnimation = this.renderer.animateNode(newTitleAnchorConfig.id, {
        ...newTitleAnchorConfig,
        rotation: 0
      }, duration * 0.62, 'easeInOutCubic');
      const centerAnimation = this.renderer.animateNode(newCenterConfig.id, {
        ...newCenterConfig,
        scale: 1,
        rotation: 0
      }, duration * 0.62, 'easeOutCubic');
      const oldCenterExit = currentCenterNode.id === newCenterConfig.id
        ? Promise.resolve()
        : this.renderer.animateNode(currentCenterNode.id, {
            ...newTitleAnchorConfig,
            opacity: 0,
            scale: 0.36,
            rotation: -0.1
          }, duration * 0.28, 'easeInCubic');

      await Promise.all([...exitAnimations, anchorAnimation, centerAnimation, oldCenterExit]);
      if (!this.isLayoutTransitionCurrent(transitionVersion)) return;

      for (const nodeId of Array.from(this.renderer.nodes.keys())) {
        if (nodeId !== newCenterConfig.id && nodeId !== newTitleAnchorConfig.id) {
          this.renderer.removeNode(nodeId);
        }
      }
      this.renderer.setNode(newCenterConfig.id, {
        ...newCenterConfig,
        rotation: 0
      });
      this.renderer.setNode(newTitleAnchorConfig.id, newTitleAnchorConfig);
      this.renderer.setLines(newLayout.lines);

      const enterNodes = newLayout.nodes.filter((node) => (
        node.id !== newCenterConfig.id
        && node.id !== newTitleAnchorConfig.id
      ));
      const enterAnimations = enterNodes.map((nodeConfig, index) => {
        this.renderer.setNode(nodeConfig.id, {
          ...nodeConfig,
          x: nodeConfig.type === 'title-anchor' ? newCenterConfig.x - 120 : newCenterConfig.x,
          y: newCenterConfig.y,
          scale: 0.16,
          opacity: 0,
          rotation: index % 2 === 0 ? -0.12 : 0.12
        });
        return new Promise((resolve) => {
          this.scheduleTransitionTimeout(() => {
            if (!this.isLayoutTransitionCurrent(transitionVersion)) {
              resolve();
              return;
            }
            this.renderer.animateNode(nodeConfig.id, {
              ...nodeConfig,
              rotation: 0
            }, duration * 0.3, 'easeOutCubic').then(resolve);
          }, Math.min(index, 5) * 10);
        });
      });

      await Promise.all(enterAnimations);
      if (!this.isLayoutTransitionCurrent(transitionVersion)) return;
      this.currentLayout = newLayout;
      this.renderer.renderingLoop = false;
      this.renderer.render();
      return;
    }

    if (direction === 'senseToTitle' && currentTitleAnchor) {
      const exitAnimations = [];
      for (const [nodeId, node] of this.renderer.nodes) {
        if (nodeId === currentTitleAnchor.id) continue;
        const isCurrentCenter = currentCenterNode && nodeId === currentCenterNode.id;
        const offsetX = isCurrentCenter ? 84 : (node.x - currentTitleAnchor.x);
        const offsetY = isCurrentCenter ? 72 : (node.y - currentTitleAnchor.y);
        const distance = Math.hypot(offsetX, offsetY) || 1;
        exitAnimations.push(this.renderer.animateNode(nodeId, {
          x: node.x + (offsetX / distance) * (isCurrentCenter ? 72 : 118),
          y: node.y + (offsetY / distance) * (isCurrentCenter ? 72 : 118),
          scale: node.scale * (isCurrentCenter ? 0.42 : 0.36),
          opacity: 0,
          rotation: node.rotation + (offsetX >= 0 ? 0.18 : -0.18)
        }, duration * 0.24, 'easeInCubic'));
      }

      const anchorToCenterAnimation = this.renderer.animateNode(currentTitleAnchor.id, {
        ...newCenterConfig,
        id: currentTitleAnchor.id,
        type: 'center',
        rotation: 0
      }, duration * 0.62, 'easeInOutCubic');

      await Promise.all([...exitAnimations, anchorToCenterAnimation]);
      if (!this.isLayoutTransitionCurrent(transitionVersion)) return;

      this.setLayout(newLayout);
      const enterNodes = newLayout.nodes.filter((node) => node.id !== newCenterConfig.id);
      const enterAnimations = enterNodes.map((nodeConfig, index) => {
        this.renderer.setNode(nodeConfig.id, {
          ...nodeConfig,
          x: newCenterConfig.x,
          y: newCenterConfig.y,
          scale: 0.18,
          opacity: 0,
          rotation: index % 2 === 0 ? -0.12 : 0.12
        });
        return new Promise((resolve) => {
          this.scheduleTransitionTimeout(() => {
            if (!this.isLayoutTransitionCurrent(transitionVersion)) {
              resolve();
              return;
            }
            this.renderer.animateNode(nodeConfig.id, {
              ...nodeConfig,
              rotation: 0
            }, duration * 0.3, 'easeOutCubic').then(resolve);
          }, Math.min(index, 5) * 10);
        });
      });

      await Promise.all(enterAnimations);
      if (!this.isLayoutTransitionCurrent(transitionVersion)) return;
      this.currentLayout = newLayout;
      this.renderer.renderingLoop = false;
      this.renderer.render();
      return;
    }

    await this.fadeTransition(newLayout, duration, transitionVersion);
    if (!this.isLayoutTransitionCurrent(transitionVersion)) return;
    for (const nodeId of Array.from(this.renderer.nodes.keys())) {
      if (!newNodeIds.has(nodeId)) this.renderer.removeNode(nodeId);
    }
  }

  /**
   * 标准过渡动画
   */
  async transitionTo(newLayout, duration = 500, transitionVersion = null) {
    if (!this.isLayoutTransitionCurrent(transitionVersion)) return;
    const transitions = this.layout.calculateTransition(this.currentLayout, newLayout);

    // 阶段1: 退出的节点淡出
    if (transitions.exit.length > 0) {
      await Promise.all(
        transitions.exit.map(t =>
          this.renderer.animateNode(t.id, t.to, duration * 0.4, 'easeInCubic')
        )
      );
      if (!this.isLayoutTransitionCurrent(transitionVersion)) return;

      // 移除已退出的节点
      transitions.exit.forEach(t => this.renderer.removeNode(t.id));
    }

    // 阶段2: 添加新节点 (初始状态)
    if (!this.isLayoutTransitionCurrent(transitionVersion)) return;
    for (const t of transitions.enter) {
      this.renderer.setNode(t.id, t.from);
    }

    // 更新连线
    this.renderer.setLines(newLayout.lines);

    // 阶段3: 移动和进入动画
    const animations = [];

    transitions.move.forEach(t => {
      animations.push(
        this.renderer.animateNode(t.id, t.to, duration, 'easeOutCubic')
      );
    });

    transitions.enter.forEach(t => {
      animations.push(
        this.renderer.animateNode(t.id, t.to, duration * 0.6, 'easeOutBack')
      );
    });

    await Promise.all(animations);
    if (!this.isLayoutTransitionCurrent(transitionVersion)) return;

    this.currentLayout = newLayout;

    // 所有动画完成后，强制重启渲染循环
    this.renderer.renderingLoop = false;
    this.renderer.render();
  }

  /**
   * 淡入淡出过渡
   */
  async fadeTransition(newLayout, duration = 400, transitionVersion = null) {
    if (!this.isLayoutTransitionCurrent(transitionVersion)) return;
    // 淡出当前所有节点
    const fadeOutPromises = Array.from(this.renderer.nodes.values()).map(node =>
      this.renderer.animateNode(node.id, { opacity: 0, scale: node.scale * 0.82 }, duration * 0.45, 'easeInCubic')
    );

    await Promise.all(fadeOutPromises);
    if (!this.isLayoutTransitionCurrent(transitionVersion)) return;

    // 清空并设置新布局
    this.setLayout(newLayout);

    // 淡入新节点
    const fadeInPromises = newLayout.nodes.map(nodeConfig => {
      const node = this.renderer.nodes.get(nodeConfig.id);
      if (node) {
        node.opacity = 0;
        node.scale = nodeConfig.scale * 0.84;
        return this.renderer.animateNode(
          nodeConfig.id,
          { opacity: nodeConfig.opacity, scale: nodeConfig.scale },
          duration * 0.7,
          'easeOutBack'
        );
      }
      return Promise.resolve();
    });

    await Promise.all(fadeInPromises);
    if (!this.isLayoutTransitionCurrent(transitionVersion)) return;

    // 所有动画完成后，强制重启渲染循环
    this.renderer.renderingLoop = false;
    this.renderer.render();
  }

  /**
   * 点击节点过渡动画 (从首页到节点详情)
   */
  async clickTransition(clickedNode, newLayout, duration = 620, transitionVersion = null) {
    if (!this.isLayoutTransitionCurrent(transitionVersion)) return;
    const transitions = this.layout.calculateClickTransition(
      clickedNode,
      this.currentLayout,
      newLayout
    );

    // 阶段1: 其他节点快速淡出
    await Promise.all(
      transitions.exit.map(t =>
        this.renderer.animateNode(t.id, t.to, duration * 0.22, 'easeInCubic')
      )
    );
    if (!this.isLayoutTransitionCurrent(transitionVersion)) return;

    // 移除淡出的节点
    transitions.exit.forEach(t => this.renderer.removeNode(t.id));

    // 阶段2: 被点击节点移动并放大到中心
    if (transitions.special) {
      const t = transitions.special;
      await this.renderer.animateNode(t.id, t.to, duration * 0.38, 'easeOutCubic');
      if (!this.isLayoutTransitionCurrent(transitionVersion)) return;

      // 重命名节点ID (从 root-xxx 到 center-xxx)
      const centerNode = newLayout.nodes.find(n => n.type === 'center');
      if (centerNode) {
        const oldNode = this.renderer.nodes.get(t.id);
        this.renderer.removeNode(t.id);
        this.renderer.setNode(centerNode.id, {
          ...oldNode,
          ...centerNode,
          id: centerNode.id
        });
      }
    }

    // 更新连线
    this.renderer.setLines(newLayout.lines);

    // 阶段3: 母域和子域节点紧凑出现
    const enterAnimations = transitions.enter.map((t, index) => {
      if (!this.isLayoutTransitionCurrent(transitionVersion)) {
        return Promise.resolve();
      }
      // 添加节点
      this.renderer.setNode(t.id, t.from);

      // 延迟进入
      return new Promise(resolve => {
        this.scheduleTransitionTimeout(() => {
          if (!this.isLayoutTransitionCurrent(transitionVersion)) {
            resolve();
            return;
          }
          this.renderer.animateNode(t.id, t.to, duration * 0.3, 'easeOutCubic')
            .then(resolve);
        }, Math.min(index, 6) * 14);
      });
    });

    await Promise.all(enterAnimations);
    if (!this.isLayoutTransitionCurrent(transitionVersion)) return;

    this.currentLayout = newLayout;

    // 所有动画完成后，强制重启渲染循环
    this.renderer.renderingLoop = false;
    this.renderer.render();
  }

  /**
   * 节点详情之间的切换动画
   */
  async nodeToNodeTransition(clickedNode, newLayout, duration = 360, transitionVersion = null) {
    if (!this.isLayoutTransitionCurrent(transitionVersion)) return;
    if (!clickedNode) {
      await this.transitionTo(newLayout, duration, transitionVersion);
      return;
    }

    // 找到被点击的节点（母域或子域）
    const sourceNode = this.renderer.nodes.get(clickedNode.id);
    if (!sourceNode) {
      await this.transitionTo(newLayout, duration, transitionVersion);
      return;
    }

    const transitions = {
      exit: [],
      enter: [],
      special: null
    };

    // 中心节点和被点击节点：特殊处理
    const newCenterNode = newLayout.nodes.find(n => n.type === 'center');

    // 阶段1: 旧中心节点和其他节点快速移开/缩小
    for (const [id, node] of this.renderer.nodes) {
      if (id === clickedNode.id) {
        // 被点击的节点：移动到中心并放大
        transitions.special = {
          id,
          from: { ...node },
          to: { ...newCenterNode, id }
        };
      } else {
        // 其他节点沿着远离当前焦点的方向退出，避免完全随机带来的噪声感。
        const dx = node.x - sourceNode.x;
        const dy = node.y - sourceNode.y;
        const length = Math.sqrt(dx * dx + dy * dy) || 1;
        const distance = 170 + Math.min(110, length * 0.28);
        transitions.exit.push({
          id,
          from: { ...node },
          to: {
            x: node.x + (dx / length) * distance,
            y: node.y + (dy / length) * distance,
            opacity: 0,
            scale: node.scale * 0.52,
            rotation: node.rotation + (dx >= 0 ? 0.08 : -0.08)
          }
        });
      }
    }

    // 执行退出和移动动画
    const exitAnimations = transitions.exit.map(t =>
      this.renderer.animateNode(t.id, t.to, duration * 0.24, 'easeInCubic')
    );

    let specialAnimation = Promise.resolve();
    if (transitions.special) {
      specialAnimation = this.renderer.animateNode(
        transitions.special.id,
        transitions.special.to,
        duration * 0.34,
        'easeOutCubic'
      );
    }

    await Promise.all([...exitAnimations, specialAnimation]);
    if (!this.isLayoutTransitionCurrent(transitionVersion)) return;

    // 移除退出的节点
    transitions.exit.forEach(t => this.renderer.removeNode(t.id));

    // 重命名被点击节点为中心节点
    if (transitions.special && newCenterNode) {
      const node = this.renderer.nodes.get(transitions.special.id);
      this.renderer.removeNode(transitions.special.id);
      this.renderer.setNode(newCenterNode.id, {
        ...node,
        ...newCenterNode,
        id: newCenterNode.id,
        type: 'center'
      });
    }

    // 更新连线
    this.renderer.setLines(newLayout.lines);

    // 阶段2: 新的母域和子域节点紧凑出现
    const newNodes = newLayout.nodes.filter(n => n.type !== 'center');

    const enterAnimations = newNodes.map((nodeConfig, index) => {
      if (!this.isLayoutTransitionCurrent(transitionVersion)) {
        return Promise.resolve();
      }
      // 从中心位置开始
      this.renderer.setNode(nodeConfig.id, {
        ...nodeConfig,
        x: newCenterNode.x,
        y: newCenterNode.y,
        scale: 0.12,
        opacity: 0,
        rotation: nodeConfig.rotation || ((index % 2 === 0) ? -0.12 : 0.12)
      });

      // 延迟进入
      return new Promise(resolve => {
        this.scheduleTransitionTimeout(() => {
          if (!this.isLayoutTransitionCurrent(transitionVersion)) {
            resolve();
            return;
          }
          this.renderer.animateNode(nodeConfig.id, {
            ...nodeConfig,
            rotation: 0
          }, duration * 0.34, 'easeOutCubic')
            .then(resolve);
        }, Math.min(index, 6) * 12);
      });
    });

    await Promise.all(enterAnimations);
    if (!this.isLayoutTransitionCurrent(transitionVersion)) return;

    this.currentLayout = newLayout;

    // 所有动画完成后，强制重启渲染循环
    this.renderer.renderingLoop = false;
    this.renderer.render();
  }

  /**
   * 更新搜索结果 (仅首页)
   */
  async updateSearchResults(searchResults) {
    if (this.currentScene !== 'home') return;

    // 重新计算布局并过渡
    // 注意：需要从外部传入rootNodes和featuredNodes，这里简化处理
    const rootNodes = this.currentLayout.nodes
      .filter(n => n.type === 'root')
      .map(n => n.data);

    const featuredNodes = this.currentLayout.nodes
      .filter(n => n.type === 'featured')
      .map(n => n.data);

    const newLayout = this.layout.calculateHomeLayout(rootNodes, featuredNodes, searchResults);
    await this.transitionTo(newLayout, 400);
  }

  /**
   * 调整大小
   */
  resize(width, height) {
    this.layout.resize(width, height);
    this.renderer.resize(width, height);
    this.refreshMainViewViewportInsets();

    // 重新计算并应用当前布局
    if (this.currentLayoutSource?.mode === 'starMap' && this.currentLayout.nodes.length > 0) {
      const newLayout = this.layout.calculateStarMapLayout(
        this.currentLayoutSource.graph,
        {
          layer: this.currentLayoutSource.scene === 'titleDetail' ? 'title' : 'sense'
        }
      );
      this.setLayout(newLayout);
      this.frameStarMapOnCenter(newLayout);
      this.scheduleStarMapCenterRefit();
      this.scheduleStarMapMeasuredLabelPass(newLayout);
    } else if (this.currentScene === 'home' && this.currentLayout.nodes.length > 0) {
      const rootNodes = this.currentLayout.nodes
        .filter(n => n.type === 'root')
        .map(n => n.data)
        .filter(Boolean);

      const featuredNodes = this.currentLayout.nodes
        .filter(n => n.type === 'featured')
        .map(n => n.data)
        .filter(Boolean);

      const searchResults = this.currentLayout.nodes
        .filter(n => n.type === 'search')
        .map(n => n.data)
        .filter(Boolean);

      const newLayout = this.layout.calculateHomeLayout(rootNodes, featuredNodes, searchResults);
      this.setLayout(newLayout);
    } else if (this.currentScene === 'nodeDetail' && this.currentLayout.nodes.length > 0) {
      const centerNode = this.currentLayout.nodes
        .find(n => n.type === 'center')?.data;

      const parentNodes = this.currentLayout.nodes
        .filter(n => n.type === 'parent')
        .map(n => n.data)
        .filter(Boolean);

      const childNodes = this.currentLayout.nodes
        .filter(n => n.type === 'child')
        .map(n => n.data)
        .filter(Boolean);

      if (centerNode) {
        const newLayout = this.layout.calculateNodeDetailLayout(centerNode, parentNodes, childNodes);
        this.setLayout(newLayout);
        this.resetCameraToLayoutCenter();
      }
    } else if (this.currentScene === 'titleDetail' && this.currentLayout.nodes.length > 0) {
      const centerNode = this.currentLayout.nodes.find((n) => n.type === 'center')?.data;
      if (!centerNode) return;

      const graphNodes = this.currentLayout.nodes
        .filter((n) => n.type === 'title')
        .map((n) => n.data)
        .filter(Boolean);
      const levelByNodeId = {};
      graphNodes.forEach((node) => {
        const nodeId = String(node?._id || '');
        if (!nodeId) return;
        const level = Number(node?.graphLevel);
        levelByNodeId[nodeId] = Number.isFinite(level) && level > 0 ? level : 1;
      });
      levelByNodeId[String(centerNode._id)] = 0;

      const graphEdges = (Array.isArray(this.currentLayout.lines) ? this.currentLayout.lines : [])
        .map((line) => line?.edgeMeta)
        .filter(Boolean);
      const newLayout = this.layout.calculateTitleDetailLayout(centerNode, graphNodes, graphEdges, levelByNodeId);
      this.setLayout(newLayout);
      this.resetCameraToLayoutCenter();
    }
  }

  // ==================== 关联关系预览方法 ====================

  /**
   * 进入关联关系预览模式
   * @param {Object} newNodeData - 新节点数据 {name, description}
   * @param {Object} nodeA - 第一个关联节点
   * @param {string} relationType - 关系类型 'extends' | 'contains' | 'insert'
   * @param {Object} nodeB - 第二个关联节点（仅插入模式需要）
   */
  async enterAssociationPreview(newNodeData, nodeA, relationType, nodeB = null) {
    if (this.isInPreviewMode) {
      this.exitAssociationPreview();
    }

    this.isInPreviewMode = true;
    this.previewConfig = {
      newNodeData,
      nodeA,
      relationType,
      nodeB
    };

    // 进入渲染器预览模式
    this.renderer.enterPreviewMode();

    // 计算预览布局
    const previewLayout = this.layout.calculateAssociationPreviewLayout(
      newNodeData,
      nodeA,
      relationType,
      nodeB,
      this.currentLayout
    );

    // 如果需要移动现有节点，执行动画
    if (previewLayout.movements && previewLayout.movements.length > 0) {
      await this.renderer.animatePreviewLayout(previewLayout.movements, 500);
    }

    // 设置预览节点
    if (previewLayout.previewNode) {
      this.renderer.setPreviewNode('preview-new-node', previewLayout.previewNode);
    }

    // 设置预览连线
    if (previewLayout.previewLines) {
      this.renderer.setPreviewLines(previewLayout.previewLines);
    }

    return previewLayout;
  }

  /**
   * 退出关联关系预览模式（回滚所有变更）
   */
  exitAssociationPreview() {
    if (!this.isInPreviewMode) return;

    this.renderer.exitPreviewMode();
    this.isInPreviewMode = false;
    this.previewConfig = null;
  }

  /**
   * 重新播放预览动画
   */
  async replayPreview() {
    if (!this.isInPreviewMode || !this.previewConfig) return;

    const { newNodeData, nodeA, relationType, nodeB } = this.previewConfig;

    // 先退出再重新进入
    this.renderer.exitPreviewMode();

    // 短暂延迟后重新进入
    await new Promise(resolve => setTimeout(resolve, 100));

    await this.enterAssociationPreview(newNodeData, nodeA, relationType, nodeB);
  }

  /**
   * 获取当前预览配置
   */
  getPreviewConfig() {
    return this.previewConfig;
  }

  /**
   * 检查是否在预览模式
   */
  isPreviewMode() {
    return this.isInPreviewMode;
  }

  /**
   * 进入知识域动画 - 中心节点扩大并淡出，配合知识域淡入
   * @param {Function} onTransitionComplete - 过渡动画完成后的回调
   * @param {Function} onProgress - 动画进度回调 (0-1)
   */
  async enterKnowledgeDomain(onTransitionComplete, onProgress) {
    // 清除按钮（进入知识域时不需要显示）
    this.renderer.clearNodeButtons();

    const centerNode = this.currentLayout.nodes.find(n => n.type === 'center');
    if (!centerNode) {
      if (onTransitionComplete) onTransitionComplete();
      return;
    }

    const duration = 1000; // 动画时长
    const startTime = performance.now();

    // 保存初始状态
    const initialScale = centerNode.scale;
    const initialX = centerNode.x;
    const initialY = centerNode.y;
    const initialOpacity = 1;

    // 计算目标状态 - 节点需要扩大到覆盖整个画布
    const canvasWidth = this.canvas.width;
    const canvasHeight = this.canvas.height;
    const maxDimension = Math.max(canvasWidth, canvasHeight);
    const targetScale = (maxDimension / (centerNode.radius * 2)) * 1.5;
    const targetX = canvasWidth / 2;
    const targetY = canvasHeight / 2;

    // 其他节点淡出
    const otherNodes = this.currentLayout.nodes.filter(n => n.type !== 'center');
    otherNodes.forEach(n => {
      this.renderer.animateNode(n.id, { opacity: 0, scale: n.scale * 0.5 }, duration * 0.3, 'easeInCubic');
    });

    // 中心节点扩大并淡出动画
    const animate = () => {
      const elapsed = performance.now() - startTime;
      const progress = Math.min(elapsed / duration, 1);

      // 使用easeInOutCubic缓动
      const easedProgress = progress < 0.5
        ? 4 * progress * progress * progress
        : 1 - Math.pow(-2 * progress + 2, 3) / 2;

      // 更新中心节点
      const node = this.renderer.nodes.get(centerNode.id);
      if (node) {
        node.scale = initialScale + (targetScale - initialScale) * easedProgress;
        node.x = initialX + (targetX - initialX) * easedProgress;
        node.y = initialY + (targetY - initialY) * easedProgress;
        // 后半段开始淡出
        const fadeProgress = Math.max(0, (progress - 0.4) / 0.6);
        node.opacity = initialOpacity * (1 - fadeProgress);
        node.glowIntensity = 0.5 + easedProgress * 0.3 - fadeProgress * 0.5;
      }

      // 通知进度
      if (onProgress) {
        onProgress(progress);
      }

      this.renderer.render();

      if (progress < 1) {
        requestAnimationFrame(animate);
      } else {
        // 动画完成，清理节点
        otherNodes.forEach(n => this.renderer.removeNode(n.id));
        if (onTransitionComplete) {
          onTransitionComplete();
        }
      }
    };

    animate();
  }

  /**
   * 从知识域返回 - 反向动画：知识域淡出，节点从大到小淡入
   * @param {Function} onTransitionStart - 开始恢复场景的回调
   * @param {Function} onProgress - 动画进度回调 (0-1)
   * @param {Function} onTransitionComplete - 过渡动画完成后的回调
   */
  async exitKnowledgeDomain(onTransitionStart, onProgress, onTransitionComplete) {
    // 首先通知开始恢复，让知识域开始淡出
    if (onTransitionStart) {
      onTransitionStart();
    }

    const duration = 1000;
    const startTime = performance.now();

    // 计算初始状态（从放大状态开始）
    const canvasWidth = this.canvas.width;
    const canvasHeight = this.canvas.height;
    const maxDimension = Math.max(canvasWidth, canvasHeight);

    // 获取当前节点详情的中心节点配置
    const centerNodeConfig = this.currentLayout.nodes.find(n => n.type === 'center');
    if (!centerNodeConfig) {
      if (onTransitionComplete) onTransitionComplete();
      return;
    }

    const targetScale = centerNodeConfig.scale;
    const targetX = centerNodeConfig.x;
    const targetY = centerNodeConfig.y;
    const initialScale = (maxDimension / (centerNodeConfig.radius * 2)) * 1.5;
    const initialX = canvasWidth / 2;
    const initialY = canvasHeight / 2;

    // 先设置中心节点为放大状态
    this.renderer.setNode(centerNodeConfig.id, {
      ...centerNodeConfig,
      x: initialX,
      y: initialY,
      scale: initialScale,
      opacity: 0
    });

    // 反向动画：节点从大到小，从透明到可见
    const animate = () => {
      const elapsed = performance.now() - startTime;
      const progress = Math.min(elapsed / duration, 1);

      // 使用easeInOutCubic缓动
      const easedProgress = progress < 0.5
        ? 4 * progress * progress * progress
        : 1 - Math.pow(-2 * progress + 2, 3) / 2;

      // 更新中心节点
      const node = this.renderer.nodes.get(centerNodeConfig.id);
      if (node) {
        node.scale = initialScale + (targetScale - initialScale) * easedProgress;
        node.x = initialX + (targetX - initialX) * easedProgress;
        node.y = initialY + (targetY - initialY) * easedProgress;
        // 前半段淡入
        const fadeProgress = Math.min(1, progress / 0.6);
        node.opacity = fadeProgress;
        node.glowIntensity = 0.3 + fadeProgress * 0.2;
      }

      // 通知进度（反向，1到0）
      if (onProgress) {
        onProgress(1 - progress);
      }

      this.renderer.render();

      if (progress < 1) {
        requestAnimationFrame(animate);
      } else {
        // 动画完成，恢复其他节点
        const otherNodes = this.currentLayout.nodes.filter(n => n.type !== 'center');
        otherNodes.forEach((nodeConfig, index) => {
          this.renderer.setNode(nodeConfig.id, {
            ...nodeConfig,
            opacity: 0,
            scale: 0
          });
          // 延迟进入动画
          setTimeout(() => {
            this.renderer.animateNode(nodeConfig.id, nodeConfig, 400, 'easeOutBack');
          }, index * 50);
        });

        // 更新连线
        this.renderer.setLines(this.currentLayout.lines);

        // 重新设置中心节点的按钮
        if (centerNodeConfig.data) {
          this.setupCenterNodeButtons(centerNodeConfig.data);
        }

        // 确保渲染循环正常运行
        this.renderer.renderingLoop = false;
        this.renderer.render();

        if (onTransitionComplete) {
          setTimeout(onTransitionComplete, 400 + otherNodes.length * 50);
        }
      }
    };

    animate();
  }

  /**
   * 显示简单关联预览（新节点直接作为 nodeA 的母域或子域）
   * @param {Object} newNodeData - 新节点数据
   * @param {Object} nodeA - 关联节点A的完整数据（包括 parentNodesInfo, childNodesInfo）
   * @param {string} relationType - 'extends' 或 'contains'
   */
  async showSimpleAssociationPreview(newNodeData, nodeA, relationType) {
    return this.enterAssociationPreview(newNodeData, nodeA, relationType, null);
  }

  /**
   * 显示插入预览（新节点插入到 nodeA 和 nodeB 之间）
   * @param {Object} newNodeData - 新节点数据
   * @param {Object} nodeA - 关联节点A
   * @param {Object} nodeB - 关联节点B
   * @param {string} insertDirection - 插入方向 'aToB' (新节点在A-B之间，新作为A的子、B的父) 或 'bToA'
   */
  async showInsertAssociationPreview(newNodeData, nodeA, nodeB, insertDirection) {
    return this.enterAssociationPreview(newNodeData, nodeA, 'insert', {
      node: nodeB,
      direction: insertDirection
    });
  }

  /**
   * 为单个节点生成预览场景（用于在创建节点模态框中显示）
   * 这个方法会在指定的 canvas 上创建一个小型预览场景
   */
  createMiniPreviewScene(nodeA, relationType, newNodeName) {
    // 计算一个简化的预览布局
    const centerX = this.layout.centerX;
    const centerY = this.layout.centerY;
    const distance = 150;

    let previewNodePosition;
    let lineColor;

    if (relationType === 'extends') {
      // 新节点作为 nodeA 的母域 -> 新节点在上方
      previewNodePosition = {
        x: centerX,
        y: centerY - distance
      };
      lineColor = [0.06, 0.73, 0.51, 0.8]; // 绿色
    } else {
      // 新节点作为 nodeA 的子域 -> 新节点在下方
      previewNodePosition = {
        x: centerX,
        y: centerY + distance
      };
      lineColor = [0.98, 0.75, 0.14, 0.8]; // 黄色
    }

    return {
      centerNode: {
        x: centerX,
        y: centerY,
        label: nodeA.name || 'Node A'
      },
      previewNode: {
        ...previewNodePosition,
        label: newNodeName || '新节点'
      },
      lineColor
    };
  }

  /**
   * 销毁
   */
  destroy() {
    // 确保退出预览模式
    if (this.isInPreviewMode) {
      this.exitAssociationPreview();
    }
    this.cancelPendingStarMapMeasuredLabelPass();
    this.completedStarMapMeasuredLabelKeys.clear();
    this.currentLayoutSource = null;
    this.renderer.destroy();
  }
}

export default SceneManager;
